vector<int> lisLengths(const vector<int> &a) {
    vector<int> tail, length(a.size());
    for (int i = 0; i < int(a.size()); ++i) {
        auto it = lower_bound(tail.begin(), tail.end(), a[i]);
        int pos = int(it - tail.begin());
        if (it == tail.end()) tail.push_back(a[i]);
        else *it = a[i];
        length[i] = pos + 1;
    }
    return length;
}

